    private function completionResult(int $orderId): array{$q=$this->db->prepare('SELECT order_number,customer_email,customer_first_name,customer_last_name,shipping_method,subtotal,discount_total,discount_code_snapshot,grand_total FROM orders WHERE id=?');$q->execute([$orderId]);$order=$q->fetch(PDO::FETCH_ASSOC);if(!$order)return ['ok'=>false,'message'=>'Поръчката беше приета, но данните ѝ не могат да бъдат заредени.','status'=>500];$items=$this->db->prepare('SELECT oi.product_name,oi.variant_name,oi.quantity,oi.line_total,(SELECT i.file_path FROM product_images i WHERE i.product_id=oi.product_id ORDER BY i.is_primary DESC,i.position,i.id LIMIT 1) image_path FROM order_items oi WHERE oi.order_id=? ORDER BY oi.id');$items->execute([$orderId]);$details=[];foreach($items->fetchAll(PDO::FETCH_ASSOC) as $item)$details[]=['product_name'=>(string)$item['product_name'],'variant_name'=>(string)($item['variant_name']??''),'quantity'=>(int)$item['quantity'],'line_cents'=>ProductPricingService::moneyCents((string)$item['line_total'])??0,'image_path'=>$item['image_path']!==null?(string)$item['image_path']:null];return ['ok'=>true,'order_number'=>(string)$order['order_number'],'customer_email'=>(string)$order['customer_email'],'customer_name'=>trim((string)$order['customer_first_name'].' '.(string)$order['customer_last_name']),'free_shipping'=>(string)$order['shipping_method']==='Куриер до адрес','subtotal_cents'=>ProductPricingService::moneyCents((string)$order['subtotal'])??0,'grand_total_cents'=>ProductPricingService::moneyCents((string)$order['grand_total'])??0,'discount_cents'=>ProductPricingService::moneyCents((string)$order['discount_total'])??0,'discount_code'=>(string)($order['discount_code_snapshot']??''),'payment_method'=>'Наложен платеж','shipping_label'=>(string)$order['shipping_method']==='Куриер до адрес'?'Безплатна':'Ще бъде уточнена','email_status'=>$this->emailOutbox->status($orderId,'order.created'),'items'=>$details];}
    private function enqueueCreatedEmail(int $orderId,string $orderNumber,array $contact,array $items,int $subtotal,bool $freeShipping,int $discount=0,?string $discountCode=null): void{$currency=' EUR';$intro='Получихме поръчката Ви и тя очаква потвърждение.';$lines=[$intro,'Здравейте, '.$contact['first_name'].' '.$contact['last_name'].'.','Номер на поръчка: '.$orderNumber,'','Поръчани продукти:'];foreach($items as $item)$lines[]=$item['product_name'].($item['variant_name']!==''?' — '.$item['variant_name']:'').' × '.$item['quantity'].' — '.ProductPricingService::formatCents((int)$item['line_cents']).$currency;$lines[]='';$lines[]='Сума на продуктите: '.ProductPricingService::formatCents($subtotal).$currency;if($discount>0)$lines[]='Отстъпка'.($discountCode?' ('.$discountCode.')':'').': -'.ProductPricingService::formatCents($discount).$currency;$lines[]='Сума за плащане: '.ProductPricingService::formatCents(max(0,$subtotal-$discount)).$currency;$lines[]='Доставка: '.($freeShipping?'Безплатна':'Цената ще бъде уточнена преди изпращане.');$lines[]='Плащане: Наложен платеж';$text=implode("\n",$lines);$escape=static fn(string $value):string=>htmlspecialchars($value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$rows='';foreach($items as $item)$rows.='<tr><td style="padding:10px 8px;border-bottom:1px solid #f0dfdc">'.$escape($item['product_name'].($item['variant_name']!==''?' — '.$item['variant_name']:'' )).'</td><td style="padding:10px 8px;border-bottom:1px solid #f0dfdc;text-align:center">'.(int)$item['quantity'].'</td><td style="padding:10px 8px;border-bottom:1px solid #f0dfdc;text-align:right;white-space:nowrap">'.ProductPricingService::formatCents((int)$item['line_cents']).$currency.'</td></tr>';$shipping=$freeShipping?'Безплатна':'Ще бъде уточнена';$html='<!doctype html><html lang="bg"><body style="margin:0;background:#fff7f7;font:15px Arial,sans-serif;color:#382f32"><main style="max-width:620px;margin:24px auto;padding:28px;background:#fff;border:1px solid #f2d9df;border-radius:18px"><h1 style="margin:0 0 10px;color:#8f1738;font-size:25px">Поръчката е приета успешно!</h1><p>'.$escape($intro).'</p><p>Здравейте, '.$escape($contact['first_name'].' '.$contact['last_name']).'</p><p><strong>Номер на поръчка:</strong> '.$escape($orderNumber).'<br><strong>Доставка:</strong> '.$shipping.'<br><strong>Плащане:</strong> Наложен платеж</p><table style="width:100%;border-collapse:collapse"><thead><tr><th align="left" style="padding:8px">Продукт</th><th align="center" style="padding:8px">Брой</th><th align="right" style="padding:8px">Сума</th></tr></thead><tbody>'.$rows.'</tbody></table><p style="text-align:right;margin-top:18px"><strong>Сума на продуктите: '.ProductPricingService::formatCents($subtotal).$currency.'</strong>'.($discount>0?'<br>Отстъпка'.($discountCode?' ('.$escape($discountCode).')':'').': −'.ProductPricingService::formatCents($discount).$currency:'').'<br><strong>Сума за плащане: '.ProductPricingService::formatCents(max(0,$subtotal-$discount)).$currency.'</strong></p>'.(!$freeShipping?'<p style="color:#76676a">Цената на доставката ще бъде уточнена преди изпращане.</p>':'').'<p>Благодарим Ви, че избрахте Giftcheta!</p></main></body></html>';$this->emailOutbox->enqueue($orderId,'order.created','Получихме поръчката Ви '.$orderNumber,$text,$html);}
    private function orderFilesDirectory(): string{return rtrim($this->projectRoot,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR.'storage'.DIRECTORY_SEPARATOR.'private'.DIRECTORY_SEPARATOR.'order-customizations';}
    private function copyOrderFile(string $source,string $target): bool{$directory=dirname($target);if(!is_dir($directory)&&!mkdir($directory,0750,true)&&!is_dir($directory))return false;if(!copy($source,$target))return false;@chmod($target,0640);return true;}
    private function rollbackError(string $message,int $status): array{if($this->db->inTransaction())$this->db->rollBack();foreach($this->pendingFiles as $path)if(is_file($path))@unlink($path);$this->pendingFiles=[];return $this->error($message,$status);}
    private function error(string $message,int $status): array{return ['ok'=>false,'message'=>$message,'status'=>$status];}
}
